// Results in the visible examples are always generated by the shipped core.
import { readFileSync, writeFileSync } from 'node:fs';
import { normalize } from '../docs/assets/zengin_core.js';

export const examples = [
  { id: 'company-head', label: '会社名・先頭', input: '株式会社ヤマダ', note: '株式会社を先頭の法人略語へ。' },
  { id: 'company-tail', label: '会社名・末尾', input: 'ヤマダ株式会社', note: '末尾では括弧の向きが変わります。' },
  { id: 'long-vowel', label: '長音・中黒', input: 'スーパー・マーケット', note: '長音はハイフン、中黒はピリオドへ。' },
  { id: 'voiced', label: '濁点・半濁点', input: 'ガギグ パピプ', note: '濁点・半濁点もそれぞれ一文字です。' },
  { id: 'small-kana', label: '小書きカナ', input: 'きゃっしゅ', note: '小書きカナを大文字へ。' },
  { id: 'symbols', label: '使えない記号', input: 'エービー／シー', note: '「/」は残して警告。登録名義を確認して直してください。' },
  { id: 'limit', label: '受取人名・上限', input: 'ガ'.repeat(15), note: '本ツールの上限内です。' },
  { id: 'over-limit', label: '受取人名・超過', input: 'ガ'.repeat(15) + 'ア', note: '切り捨てずに警告します。' },
];
const escape = s => s.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
export function renderExamples() {
  const rows = examples.map(e => {
    const r = normalize(e.input);
    return `<tr data-example="${e.id}"><th scope="row">${e.label}</th><td><code>${escape(e.input)}</code></td><td><code>${escape(r.output)}</code><br><span class="hint">${r.length}文字・${r.ok ? '使用可能' : '要確認'}</span></td><td>${e.note}</td><td><button type="button" data-example-input="${escape(e.input)}" aria-label="${e.label}の例を試す">試す</button></td></tr>`;
  }).join('\n');
  return `<!--zengin-examples:S-->\n<div class="scroll-wrap">\n<table id="zengin-examples">\n<thead><tr><th scope="col">用途</th><th scope="col">入力例</th><th scope="col">変換結果</th><th scope="col">確認すること</th><th scope="col">操作</th></tr></thead>\n<tbody>\n${rows}\n</tbody>\n</table>\n</div>\n<!--zengin-examples:E-->`;
}
if (process.argv[1] === new URL(import.meta.url).pathname) {
  const path = new URL('../docs/zengin-kana/index.html', import.meta.url);
  const before = readFileSync(path, 'utf8');
  const after = before.replace(/<!--zengin-examples:S-->[\s\S]*?<!--zengin-examples:E-->/, renderExamples());
  if (!before.includes('<!--zengin-examples:S-->')) throw new Error('Missing examples marker');
  if (process.argv.includes('--check')) {
    if (before !== after) throw new Error('Stale zengin examples');
  } else if (before !== after) writeFileSync(path, after);
  console.log('zengin examples: current');
}
